				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$${\text{Inhibition}}\%= \left[ {{\text{Data}}_{{({\text{compound}})}} - {\text{Data}}_{{({\text{DMSO Vehicle}})}} } \right]/\left[ {{\text{ Data}}_{{({\text{MK544 1}}0\mu {\text{M}})}} -{\text{ Data}}_{{({\text{DMSO Vehicle}})}} } \right] \times 100\% .$$\end{document}Inhibition%=Data(compound)-Data(DMSO Vehicle)/Data(MK54410μM)-Data(DMSO Vehicle)×100%.
